from pwn import *
import collections

# Connect to the server
r = remote('rev.chal.csaw.io', 8000)

# Collect 10 samples
samples = []
for i in range(10):
    line = r.recvline().decode().strip()
    samples.append(line)

r.close()

# Original string for comparison
original = "}3l3af{nl_4munguw_rdg"
print("Original:", original)
print("\nCollected samples:")
for s in samples:
    print(s)

# Perform frequency analysis
def analyze_freq(s):
    return collections.Counter(s)

print("\nFrequency Analysis:")
print("Original:", dict(analyze_freq(original)))
for i, s in enumerate(samples):
    print(f"Sample {i}:", dict(analyze_freq(s)))

# Analyze special character positions
def find_special_pos(s):
    specials = {}
    for char in "_{}'\"[]{}":
        if char in s:
            positions = [i for i, c in enumerate(s) if c == char]
            if positions:
                specials[char] = positions
    return specials

print("\nSpecial Character Positions:")
print("Original:", find_special_pos(original))
for i, s in enumerate(samples):
    print(f"Sample {i}:", find_special_pos(s))

# Analyze number positions and surrounding context
def analyze_numbers(s):
    results = {}
    for i, c in enumerate(s):
        if c.isdigit():
            context = s[max(0,i-1):i+2]
            results[i] = (c, context)
    return results

print("\nNumber Analysis:")
print("Original:", analyze_numbers(original))
for i, s in enumerate(samples):
    print(f"Sample {i}:", analyze_numbers(s))

